void upstreamUrlIsRequired() throws IOException {
    assertRejected("api.token=s3cret\n", "upstream.url is required");
}

@Test
void upstreamUrlMustBeAValidUri() throws IOException {
    assertRejected(REQUIRED + "upstream.url=https://uplink example.com\n", "upstream.url");
