@Test
void upstreamUrlMustBeHttpOrHttps() throws IOException {
    assertRejected(REQUIRED + "upstream.url=uplink.example.com/v1/events\n", "upstream.url");
    assertRejected(REQUIRED + "upstream.url=ftp://uplink.example.com/v1/events\n", "upstream.url");
}

@Test
void acceptsHttpUpstream() throws IOException {
    ServiceConfig config = ConfigLoader.load(write(REQUIRED + "upstream.url=http://localhost:8080/events\n"));

    assertEquals(URI.create("http://localhost:8080/events"), config.upstream());
}

@Test
void workerCountThatIsNotANumberIsRejected() throws IOException {
    assertRejected(REQUIRED + "worker.threads=4x\n", "worker.threads: \"4x\" is not a whole number");
}

@Test
void integerSettingsEnforceTheirMinimum() throws IOException {
    assertEquals(1, ConfigLoader.load(write(REQUIRED + "worker.threads=1\n")).workerThreads());
    assertRejected(REQUIRED + "worker.threads=0\n", "worker.threads: must be at least 1, was 0");

    assertEquals(1, ConfigLoader.load(write(REQUIRED + "queue.capacity=1\n")).queueCapacity());
    assertRejected(REQUIRED + "queue.capacity=0\n", "queue.capacity: must be at least 1, was 0");

    assertEquals(0, ConfigLoader.load(write(REQUIRED + "retry.max-attempts=0\n")).retryAttempts());
    assertRejected(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts: must be at least 0, was -1");
}

@Test
void emptyOptionalValueIsRejected() throws IOException {
    assertRejected(REQUIRED + "queue.capacity=\n", "queue.capacity: \"\" is not a whole number");
}

@Test
void timeoutWithoutAUnitIsRejected() throws IOException {
    assertRejected(REQUIRED + "request.timeout=30\n", "request.timeout: \"30\"");
}

@Test
void timeoutTooLargeForADurationIsRejected() throws IOException {
    assertRejected(REQUIRED + "request.timeout=99999999999999999999m\n", "request.timeout");
}

@Test
void metricsFlagMustBeTrueOrFalse() throws IOException {
    assertFalse(ConfigLoader.load(write(REQUIRED + "metrics.enabled=false\n")).metricsEnabled());
    assertTrue(ConfigLoader.load(write(REQUIRED + "metrics.enabled=TRUE\n")).metricsEnabled());
    assertRejected(REQUIRED + "metrics.enabled=yes\n", "metrics.enabled: \"yes\" is not true or false");
}

@Test
void misspelledKeyIsRejected() throws IOException {
    assertRejected(REQUIRED + "worker.thread=8\n", "unknown key worker.thread");
}

@Test
void reportsEveryProblemAtOnce() throws IOException {
    Path file = write("worker.threads=four\nrequest.timeout=30\n");

    String message = assertThrows(ConfigException.class, () -> ConfigLoader.load(file)).getMessage();

    assertTrue(message.contains(file.toString()), message);
    assertTrue(message.contains("upstream.url is required"), message);
    assertTrue(message.contains("api.token is required"), message);
    assertTrue(message.contains("worker.threads"), message);
    assertTrue(message.contains("request.timeout"), message);
}

@Test
void missingFileIsRejected() {
    Path missing = dir.resolve("absent.properties");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

    assertTrue(error.getMessage().contains(missing.toString()), error.getMessage());
}

private void assertRejected(String content, String expectedProblem) throws IOException {
    Path file = write(content);

    String message = assertThrows(ConfigException.class, () -> ConfigLoader.load(file)).getMessage();

    assertTrue(message.contains(expectedProblem), message);
}

private Path write(String content) throws IOException {
    return Files.writeString(dir.resolve("config.properties"), content);
}

