import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any missing, malformed, out-of-range or unknown setting is a {@link ConfigException} listing every problem
 * found, so a typo stops the deployment instead of silently running on defaults.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final String UPSTREAM_URL = "upstream.url";
    private static final String API_TOKEN = "api.token";
    private static final String WORKER_THREADS = "worker.threads";
    private static final String QUEUE_CAPACITY = "queue.capacity";
    private static final String RETRY_ATTEMPTS = "retry.max-attempts";
    private static final String REQUEST_TIMEOUT = "request.timeout";
    private static final String METRICS_ENABLED = "metrics.enabled";
    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_ATTEMPTS, REQUEST_TIMEOUT, METRICS_ENABLED);
    private static final Set<String> UPSTREAM_SCHEMES = Set.of("http", "https");

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Properties properties) {
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        ConfigLoader loader = new ConfigLoader(read(file));
        ServiceConfig config = loader.parse();
        if (!loader.problems.isEmpty()) {
            throw new ConfigException("Invalid configuration in " + file + ":\n  - " + String.join("\n  - ", loader.problems));
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("Cannot read configuration file " + file + ": " + e, e);
        }
        return properties;
    }

    private ServiceConfig parse() {
        rejectUnknownKeys();
        return new ServiceConfig(
                upstream(),
                required(API_TOKEN),
                intValue(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                intValue(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                intValue(RETRY_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                booleanValue(METRICS_ENABLED));
    }

    private void rejectUnknownKeys() {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key " + key + " (expected one of " + new TreeSet<>(KNOWN_KEYS) + ")");
            }
        }
    }

    private String required(String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private URI upstream() {
        String raw = required(UPSTREAM_URL);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            if (uri.getScheme() == null || !UPSTREAM_SCHEMES.contains(uri.getScheme().toLowerCase()) || uri.getHost() == null) {
                problems.add(UPSTREAM_URL + ": \"" + raw + "\" is not an http or https URL with a host");
            }
            return uri;
        } catch (URISyntaxException e) {
            problems.add(UPSTREAM_URL + ": \"" + raw + "\" is not a valid URL (" + e.getMessage() + ")");
            return null;
        }
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        int value;
        try {
            value = Integer.parseInt(raw.trim());
        } catch (NumberFormatException e) {
            problems.add(key + ": \"" + raw.trim() + "\" is not a whole number");
            return defaultValue;
        }
        if (value < minimum) {
            problems.add(key + ": must be at least " + minimum + ", was " + value);
        }
        return value;
    }

    private Duration duration(String key, Duration defaultValue) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            problems.add(key + ": \"" + raw.trim() + "\" is not a whole number followed by ms, s or m (e.g. 30s)");
            return defaultValue;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(key + ": \"" + raw.trim() + "\" is too large");
            return defaultValue;
        }
    }

    private boolean booleanValue(String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (!value.equalsIgnoreCase("true") && !value.equalsIgnoreCase("false")) {
            problems.add(key + ": \"" + value + "\" is not true or false");
        }
        return Boolean.parseBoolean(value);
    }
}

