            if (uri.getScheme() == null || !UPSTREAM_SCHEMES.contains(uri.getScheme().toLowerCase()) || uri.getHost() == null) {
                problems.add(UPSTREAM_URL + ": \"" + raw + "\" is not an http or https URL with a host");
            }
            return uri;
