        } catch (NumberFormatException e) {
            problems.add(key + ": \"" + raw.trim() + "\" is not a whole number");
            return defaultValue;
        }
        if (value < minimum) {
            problems.add(key + ": must be at least " + minimum + ", was " + value);
        }
        return value;
    }

    private Duration duration(String key, Duration defaultValue) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            problems.add(key + ": \"" + raw.trim() + "\" is not a whole number followed by ms, s or m (e.g. 30s)");
            return defaultValue;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(key + ": \"" + raw.trim() + "\" is too large");
            return defaultValue;
        }
    }

    private boolean booleanValue(String key) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (!value.equalsIgnoreCase("true") && !value.equalsIgnoreCase("false")) {
            problems.add(key + ": \"" + value + "\" is not true or false");
        }
        return Boolean.parseBoolean(value);
    }
}

